import json, sys
from datetime import datetime, timezone


def parse_aware_utc(s):
    """Parse an offset-aware ISO8601 string to a UTC-aware datetime.
    Returns None for naive strings (which must be skipped)."""
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        return None  # naive -> skip per contract
    return dt.astimezone(timezone.utc)


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of_raw = data.get("as_of")
    as_of = parse_aware_utc(as_of_raw) if isinstance(as_of_raw, str) else None

    reminders = data.get("reminders", [])

    rows = []  # (utc_instant, id, title)
    for r in reminders:
        if r.get("completed"):
            continue  # skip completed
        due = r.get("due")  # None when key missing
        if not isinstance(due, str):
            continue  # null / missing / non-string -> skip
        dt = parse_aware_utc(due)
        if dt is None:
            continue  # naive due -> skip
        # include only due AT OR BEFORE as_of, by actual instant
        if as_of is not None and dt <= as_of:
            rows.append((dt, r["id"], r["title"]))

    # sort by actual due instant, then id
    rows.sort(key=lambda t: (t[0], t[1]))

    out = [
        {
            "id": i,
            "title": t,
            "due_utc": d.strftime("%Y-%m-%dT%H:%M:%SZ"),
        }
        for (d, i, t) in rows
    ]

    print(json.dumps(out, ensure_ascii=False))


main()
